(function(){
'use strict';
const data=window.HUB_DATA, core=window.HubCore, esc=core.escapeHTML, title=core.titleCase, main=document.getElementById('main');
const all=[...data.resources,...data.databases,...window.ProjectExamples.searchRecords(data.projectExamples||[]),...window.IntramuralFunding.searchRecords(data.intramuralFunding||[])], byId=new Map(all.map(r=>[r.id,r]));
const external=(r,cls='')=>`<a class="${cls}" href="${esc(r.url)}" ${r.url.startsWith('#')?'':'target="_blank" rel="noopener noreferrer"'}>${esc(title(r.name))} ${r.url.startsWith('#')?'':'<span aria-hidden="true">↗</span>'}</a>`;
const groupOrder=['IRB and approvals','Forms and documents','REDCap and data tools','Study design and statistics','Literature and systematic reviews','Funding and career development','Writing and reporting','Clinical trials and collaboration','Getting started','Research support','Project examples'];
function searchForm(value='',placeholder='Search resources, tools, or study names…'){return `<form class="search-form" data-search><label><span class="sr-only">Search resources</span><input type="search" name="q" aria-label="Search resources" value="${esc(value)}" placeholder="${esc(placeholder)}"></label><button>Search</button></form>`;}
function card(r,access=false){return `<article class="resource-card"><h3>${external(r)}</h3>${r.badges?.length?`<div class="access-badges" aria-label="Access Requirements">${r.badges.map(b=>`<span>${esc(b)}</span>`).join('')}</div>`:''}<p>${esc(r.summary)}</p>${access?`<div class="access-note"><h4>Access Requirements</h4><p>${esc(r.access)}</p>${r.accessUrl?`<a href="${esc(r.accessUrl)}" target="_blank" rel="noopener noreferrer">How to Request Access ↗</a>`:''}${r.dictionaryUrl?`<a href="${esc(r.dictionaryUrl)}" target="_blank" rel="noopener noreferrer">Data Documentation ↗</a>`:''}</div>`:''}</article>`;}

function groups(items,topics){return topics.map(t=>{const group=items.filter(r=>(r.type==='database'?r.topic:r.category)===t);return group.length?`<section class="topic-group"><h2>${esc(title(t))} <small>${group.length}</small></h2><div class="directory-grid">${group.map(r=>card(r,r.type==='database')).join('')}</div></section>`:'';}).join('');}
function pageHead(title,description){return `<section class="page-head"><div class="container"><h1>${esc(core.titleCase(title))}</h1><p>${esc(description)}</p></div></section>`;}
function home(){return `<section class="hero"><div class="container home-intro"><p class="eyebrow">Clinical &amp; translational research</p><h1>Research Resources.<br><em>One Place. Direct Access.</em></h1><p class="lead">For LSU Health New Orleans PCCM faculty and fellows—and students and residents starting a research project.</p>${searchForm()}</div></section><section class="section"><div class="container"><div class="section-heading"><h2>Frequently Needed</h2><a href="#resources">All Research Resources →</a></div><div class="quick-links task-launch">${[
 ['Plan and Launch a Project','Define the question and get design advice early.',['lsu-biostatistics','training','protocol-templates','consent-templates','irb-start','kuali-login','kuali']],
 ['Collect and Manage Data','Set up a project or find data for a secondary analysis.',['redcap-login','redcap-start','read-center']],
 ['Find Support and Share Work','Find funding, institutional support, and a presentation slot.',['research-dashboard','lsu-funding']]
].map(([heading,description,ids],i)=>`<div><h3>${esc(title(heading))}</h3><p>${description}</p><ul>${ids.map(id=>`<li>${external(byId.get(id))}</li>`).join('')}${i===0?'<li><a href="#examples">Project Examples and Specific Aims</a></li>':''}${i===1?'<li><a href="#databases">PCCM Databases</a></li>':''}${i===2?'<li><a href="#conferences">Research Conference Sign-Up</a></li><li><a href="#microgrants">Lowenstein PCCM Micro-Grants</a></li>':''}</ul></div>`).join('')}</div><details class="project-guide"><summary>Start a Project: A Practical Guide</summary><p>Use these checkpoints with your mentor. Study design and statistical consultation should begin before the protocol is finalized.</p><ol><li><strong>Define the Question and Design.</strong> Identify a mentor, check feasibility, and ${external(byId.get('lsu-biostatistics'))}.</li><li><strong>Choose the Data Path.</strong> For an existing dataset, review its variables, release, access rules, and agreements in <a href="#databases">PCCM Databases</a>. For new collection, plan the measures and data structure with ${external(byId.get('redcap-start'))}.</li><li><strong>Prepare Training and Study Documents.</strong> Check ${external(byId.get('training'))}; use official ${external(byId.get('protocol-templates'))} and ${external(byId.get('consent-templates'))} as applicable.</li><li><strong>Confirm the Required Review.</strong> Follow the ${external(byId.get('irb-start'))} and submit through ${external(byId.get('kuali-login'))}. Seek an institutional determination when unsure about human-subjects or exemption status.</li><li><strong>Activate the Study.</strong> Complete applicable approvals, access agreements, and permissions before collecting or accessing research data. Test your collection forms and finalize the analysis plan.</li><li><strong>Analyze and Share.</strong> Use <a href="#resources?category=Study%20design%20and%20statistics">Design and Statistics Support</a> and present at the <a href="#conferences">Research Conference</a>.</li></ol></details></div></section><section class="section alt"><div class="container home-modules"><div><p class="eyebrow">Data for your next question</p><h2>PCCM Databases</h2><p>${data.databases.length} databases in ${data.topics.length} topics: critical care, pulmonary cohorts, imaging, population studies, and molecular data.</p><a class="button" href="#databases">Browse PCCM Databases →</a><p class="download-inline"><a href="${data.download}" download>Download the Original Word Directory ↓</a></p></div><div><p class="eyebrow">Share work in progress</p><h2>PCCM Research Conference</h2><p><strong>2nd &amp; 4th Wednesdays @ noon</strong></p><p>Present a new idea, work in progress, results, or a manuscript.</p><a class="button" href="#conferences">Schedule &amp; presenter sign-up →</a></div><div><p class="eyebrow">Low-friction project support</p><h2>Lowenstein PCCM Micro-Grants</h2><p>For LSU Health New Orleans medical students, residents, and fellows working on PCCM-related research.</p><a class="button" href="#microgrants">Apply or view recipients →</a></div></div></section><section class="section"><div class="container"><h2>Learn From Project Examples</h2><p>See how a focused question connects to a feasible design and a valid conclusion. Use specific aims and study-planning worksheets to develop your own project.</p><p><a class="button" href="#examples">Project Examples and Development Tools →</a></p><h2>More Tools for Your Research</h2><div class="task-chips">${[['Study design and statistics','Design & statistics'],['Literature and systematic reviews','Literature searches'],['Funding and career development','Funding & career development'],['Writing and reporting','Writing & reporting'],['Clinical trials and collaboration','Trials & collaboration']].map(([key,label])=>`<a href="#resources?category=${encodeURIComponent(key)}">${esc(title(label))} →</a>`).join('')}</div></div></section>`;}
function directory(route,isDatabase=false){const topics=isDatabase?data.topics:groupOrder;const selected=route.params.get(isDatabase?'topic':'category')||'all';return pageHead(isDatabase?'PCCM Databases':'Research Resources',isDatabase?'External datasets and registries for PCCM research. Review the summary and access requirements before planning your study.':'Practical tools and support, grouped by task. Each title opens the official resource directly.')+`<div class="container directory-section">${!isDatabase?'<p><a href="#examples">Project Examples: Abstracts, Posters, Specific Aims, and Protocol Planning →</a></p>':''}${isDatabase?`<p class="directory-download"><a href="${data.download}" download>Download the Original 40-Database Directory (Word) ↓</a></p><p class="quiet-note">The online directory includes additional datasets beyond the original Word download. Dataset access is managed by each provider; this hub does not grant permissions.</p>`:''}<div class="directory-controls">${searchForm(route.params.get('q')||'')}<label>${isDatabase?'Database topic':'Research task'}<select id="directory-filter"><option value="all">All ${isDatabase?data.topics.length+' topics':'tasks'}</option>${topics.map(t=>`<option value="${esc(t)}" ${selected===t?'selected':''}>${esc(title(t))}</option>`).join('')}</select></label></div><p id="results-count" role="status"></p>${isDatabase?'<p><a href="#resources">Search All Research Resources and Databases →</a></p>':''}<div id="directory-results"></div></div>`;}
function conferences(){return pageHead('PCCM Research Conference','Second and fourth Wednesdays at noon · Central Time')+`<div class="container section"><div class="conference-intro"><div><h2>Present Your Research</h2><p>Choose a date and add your name, LSU Health email, and presentation topic. New projects, work in progress, results, and manuscripts are welcome.</p><p class="quiet-note">Dates follow the section’s recurring schedule. Location and any holiday changes will be confirmed by the section.</p></div><a href="${esc(data.conferenceUrl)}" target="_blank" rel="noopener noreferrer">LSU Health PCCM conferences ↗</a></div><div id="research-schedule" aria-live="polite"></div><div id="booking-panel"></div></div>`;}
function microgrants(){const recipients=data.micrograntRecipients||[];return pageHead('Lowenstein PCCM Micro-Grants','Small requests. A short application. Support for PCCM-related research.')+`<div class="container section grants-layout"><article><h2>Apply for Project Support</h2><p>Open to LSU Health New Orleans <strong>medical students, residents, and fellows</strong> working on pulmonary or critical care research.</p><p>Tell us briefly what you are studying, what you need, and how much funding you are requesting. No proposal attachment or CV is needed.</p><form id="microgrant-form" class="application-form"><div class="form-pair"><label>Your name<input name="name" autocomplete="name" required maxlength="100"></label><label>LSU Health email<input name="email" type="email" autocomplete="email" placeholder="you@lsuhsc.edu" pattern="[^@\\s]+@lsuhsc\\.edu" required maxlength="254"></label></div><label>Training level<select name="level" required><option value="">Select your training level</option><option>Medical student</option><option>Resident</option><option>Fellow</option></select></label><label>1. Short description of your research project<textarea name="project" rows="4" required maxlength="2500" placeholder="What question are you asking, and how will you study it?"></textarea></label><label>2. What do you need the funds for?<textarea name="need" rows="3" required maxlength="2000" placeholder="Describe the items, services, or other project costs."></textarea></label><label>3. Budget requested (USD)<input name="budget" type="number" min="1" max="10000000" step="0.01" inputmode="decimal" required placeholder="Amount requested"></label><div class="form-trap" aria-hidden="true"><label>Leave blank<input name="website" tabindex="-1" autocomplete="off"></label></div><p class="quiet-note">Do not include patient names, identifiers, or confidential study data. Applications are reviewed before funding decisions are made.</p><button class="button" type="submit" id="grant-submit">Submit application</button><p id="grant-status" role="status" tabindex="-1"></p></form></article><aside class="grant-aside"><p class="eyebrow">A simple request</p><h2>Three Things We Need</h2><ol><li>A short project description</li><li>What the funding will pay for</li><li>The amount requested</li></ol><p>For research related to pulmonary and critical care medicine.</p></aside></div><section class="section alt" id="recipients"><div class="container"><h2>Lowenstein PCCM Micro-Grants Recipients</h2><p>Recipients and the PCCM research projects supported by this program.</p>${recipients.length?`<div class="directory-grid">${recipients.map(r=>`<article class="resource-card"><p class="card-tag">${esc(r.level)}${r.year?' · '+esc(r.year):''}</p><h3>${esc(title(r.name))}</h3><h4>${esc(title(r.project))}</h4><p>${esc(r.summary)}</p></article>`).join('')}</div>`:'<p class="recipient-empty">Recipient names and project summaries will be posted here as awards are announced.</p>'}</div></section>${window.IntramuralFunding.render(data.intramuralFunding||[],current.params.has('intramural'))}`;}
function about(){return pageHead('About CTS Research Hub','Research Resources for the LSU Health New Orleans PCCM community.')+`<div class="container section about-copy"><p>This hub brings together PCCM databases, institutional research tools, funding, study design support, and opportunities to present and develop research.</p><p>Resource titles link directly to their official sources. The hub is hosted outside the LSU Health institutional website; official policies, services, and access requirements remain with the linked offices.</p><p>The Lowenstein PCCM Micro-Grants program supports PCCM-related projects by LSU Health New Orleans medical students, residents, and fellows.</p><a class="button outline" href="#resources">Browse Research Resources →</a></div>`;}
let current,searchValue='',filterValue='all';
function updateResults(){if(!['resources','databases'].includes(current.page))return;const isDb=current.page==='databases',searchPool=isDb?data.databases:all,options={query:searchValue};if(isDb)options.topic=filterValue;else options.category=filterValue;let items=core.filterResources(searchPool,options);if(!isDb&&!searchValue)items=items.filter(r=>r.type!=='database');const groupedTopics=isDb?data.topics:[...groupOrder,...(searchValue?data.topics:[])];document.getElementById('results-count').textContent=`${items.length} ${isDb?'databases':'resources'}`;document.getElementById('directory-results').innerHTML=items.length?groups(items,groupedTopics):'<p class="empty">No matches. Try another term or research task.</p>';}
function bind(){document.querySelectorAll('[data-search]').forEach(form=>{form.addEventListener('submit',event=>{event.preventDefault();const q=new FormData(form).get('q').trim();if(['resources','databases'].includes(current.page)){searchValue=q;updateResults();}else location.hash='#resources?q='+encodeURIComponent(q);});if(['resources','databases'].includes(current.page))form.querySelector('input').addEventListener('input',event=>{searchValue=event.target.value;updateResults();});});document.getElementById('directory-filter')?.addEventListener('change',event=>{filterValue=event.target.value;updateResults();});if(current.page==='examples')window.ProjectExamples.mount(data.projectExamples||[],current.params);if(current.page==='conferences')window.HubSchedule.mount(current.params);if(current.page==='microgrants')window.HubSchedule.bindGrant();}
function render(){current=core.parseRoute(location.hash);if(current.page==='detail'){const r=byId.get(current.id);main.innerHTML=r?pageHead(r.name,r.summary)+`<div class="container section"><p>${esc(r.access)}</p>${external(r,'button')}</div>`:pageHead('Resource not found','Browse the directory for available resources.');return;}const titles={home:'CTS Research Hub',resources:'Research Resources',databases:'PCCM Databases',conferences:'PCCM Research Conference',microgrants:'Lowenstein PCCM Micro-Grants',examples:'Project Examples',about:'About'};document.title=titles[current.page]+(current.page==='home'?'':' | CTS Research Hub');document.querySelectorAll('[data-nav]').forEach(a=>{if(a.dataset.nav===current.page||(current.page==='examples'&&a.dataset.nav==='resources'))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.getElementById('primary-nav').classList.remove('open');document.getElementById('menu-toggle').setAttribute('aria-expanded','false');searchValue=current.params.get('q')||'';filterValue=current.params.get(current.page==='databases'?'topic':'category')||'all';main.innerHTML=current.page==='home'?home():['resources','databases'].includes(current.page)?directory(current,current.page==='databases'):current.page==='conferences'?conferences():current.page==='microgrants'?microgrants():current.page==='examples'?window.ProjectExamples.page(data.projectExamples||[]):about();bind();updateResults();window.scrollTo(0,0);}
window.addEventListener('keydown',event=>{if(event.key!=='/'||event.ctrlKey||event.metaKey||event.altKey||/INPUT|TEXTAREA|SELECT/.test(event.target?.tagName)||event.target?.isContentEditable)return;event.preventDefault();const input=document.querySelector?.('input[type=search]');if(input){input.focus();input.select();}else{location.hash='#resources';setTimeout(()=>document.querySelector?.('input[type=search]')?.focus(),0);}});
document.getElementById('menu-toggle').addEventListener('click',()=>{const open=document.getElementById('primary-nav').classList.toggle('open');document.getElementById('menu-toggle').setAttribute('aria-expanded',String(open));});window.addEventListener('hashchange',()=>{if(location.hash==='#main'){main.focus();return;}render();main.focus({preventScroll:true});});render();
})();
